[BurstCompile]
struct SortJob : IJob
{
    public NativeArray<int> values;
    public void Execute() => values.Sort();   // one Execute, one worker thread
}

JobHandle h = new SortJob { values = values }.Schedule();

[BurstCompile]
struct ScaleJob : IJobParallelFor
{
    [ReadOnly] public NativeArray<float> input;
    public NativeArray<float> output;
    public float k;

    public void Execute(int index)
    {
        output[index] = input[index] * k;   // only your own index
    }
}

JobHandle h = new ScaleJob { input = input, output = output, k = 2f }
    .Schedule(input.Length, 64);            // length, batch size

[BurstCompile]
struct DecayJob : IJobFor
{
    public NativeArray<float> heat;
    public float k;
    public void Execute(int i) => heat[i] *= k;
}

var job = new DecayJob { heat = heat, k = 0.95f };
job.Run(heat.Length);                                     // main thread, in order
JobHandle a = job.Schedule(heat.Length, default);         // one worker, in order
JobHandle b = job.ScheduleParallel(heat.Length, 64, a);   // many workers, in batches

[BurstCompile]
struct VelocityJob : IJobParallelForTransform
{
    [ReadOnly] public NativeArray<Vector3> velocity;
    public float dt;

    public void Execute(int index, TransformAccess transform)
