        transform.position += velocity[index] * dt;
    }
}

var transforms = new TransformAccessArray(bulletTransforms);   // Transform[]; Dispose() later
JobHandle h = new VelocityJob { velocity = velocity, dt = Time.deltaTime }
    .Schedule(transforms);

