using Unity.Burst;
using Unity.Collections;
using Unity.Jobs;
using Unity.Mathematics;

[BurstCompile]
struct DistanceJob : IJobParallelFor
{
    [ReadOnly] public NativeArray<float3> positions;
    public NativeArray<float> distances;
    public float3 target;

    public void Execute(int index)   // one element per call
    {
        distances[index] = math.distance(positions[index], target);
    }
}

static class DistanceScheduler
{
    public static JobHandle ScheduleDistances(NativeArray<float3> positions, NativeArray<float> distances, float3 target)
    {
        var job = new DistanceJob { positions = positions, distances = distances, target = target };
        return job.Schedule(positions.Length, 64);   // length, batch size
    }
}

