partial struct MoveJob : IJobEntity
{
    public float dt;
    void Execute(ref LocalTransform transform, in Speed speed)
    {
        transform.Position.y += speed.Value * dt;
    }
}

// in ISystem.OnUpdate:
new MoveJob { dt = SystemAPI.Time.DeltaTime }.ScheduleParallel();

